from __future__ import annotations

"""Single-home browser shell connecting the three document-defined features."""

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import re


PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Banking Agentic AI</title>
<style>:root{--navy:#173d62;--blue:#1769b3;--green:#86bc25;--purple:#6657f5;--bg:#f4f6f8;--ink:#152536}*{box-sizing:border-box}body{margin:0;font-family:Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--ink)}aside{position:fixed;inset:0 auto 0 0;width:265px;padding:26px 20px;background:var(--navy);color:#fff}.brand{display:flex;gap:12px;align-items:center;padding-bottom:22px;border-bottom:1px solid #ffffff24}.brand small{display:block;color:#bfd0e0}.mark{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:var(--green);color:var(--navy);font-weight:900}.nav{display:grid;gap:8px;margin-top:24px}.nav button{background:transparent;color:#dce8f2;text-align:left}.nav button.active,.nav button:hover{background:#ffffff18}.scope{position:absolute;bottom:24px;left:20px;right:20px;padding:14px;border-radius:14px;background:#0d2d4c;color:#bfd0e0;font-size:.82rem}main{margin-left:265px;padding:30px 44px}header{display:flex;justify-content:space-between;gap:20px;padding-bottom:20px;border-bottom:1px solid #d9e0e7}h1{margin:4px 0;color:var(--blue)}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:.72rem;font-weight:800;color:#66788a}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:20px}.features{grid-template-columns:repeat(3,minmax(0,1fr))}.card{padding:23px;border-radius:16px;background:#fff;box-shadow:0 7px 24px #173d6210}.card h2{margin-top:0;color:var(--navy)}.feature{display:flex;flex-direction:column;min-height:285px;border-top:6px solid var(--blue)}.feature:nth-child(2){border-color:var(--purple)}.feature:nth-child(3){border-color:var(--green)}.feature button{margin-top:auto}.num{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#e6f1fb;color:var(--blue);font-weight:900;margin-bottom:18px}label{display:grid;gap:6px;margin-top:10px;font-weight:650}input,select,textarea,button{width:100%;padding:11px 12px;border:1px solid #ccd6e0;border-radius:10px;font:inherit}textarea{min-height:120px}button{border:0;background:var(--blue);color:#fff;font-weight:700;cursor:pointer}.secondary{width:auto;background:#fff;color:var(--navy);border:1px solid #ccd6e0}.result{max-height:430px;overflow:auto;white-space:pre-wrap;padding:14px;border-radius:12px;background:#f7f9fb;font:12px Consolas,monospace}.hidden{display:none}.notice{background:#e8e5ff;color:#4034a5}.login{max-width:520px;margin:7vh auto}.login aside{position:static;width:auto;border-radius:20px}.login main{margin:0;padding:20px}@media(max-width:1080px){.features{grid-template-columns:1fr}}@media(max-width:850px){aside{position:static;width:auto}.scope{display:none}main{margin:0;padding:20px}.grid{grid-template-columns:1fr}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap}}</style></head><body>
<section id="app"><aside><div class="brand"><span class="mark">B</span><div><b>Banking Agentic AI</b><small>Unified feature home</small></div></div><nav class="nav"><button class="active" onclick="showView('home',this,'Feature Home')">Home</button><button onclick="showView('statements',this,'Bank Statement Analysis')">Bank Statements</button><button onclick="showView('verification',this,'Income & Employment Verification')">Income Verification</button><button onclick="showView('dormancy',this,'Dormancy & Escheatment')">Dormancy</button><button onclick="showView('approvals',this,'Approvals')">Approvals</button></nav><div class="scope">01 Bank statements<br>02 Income / AA verification<br>03 Dormancy & escheatment</div></aside><main><header><div><span class="eyebrow">One platform · three accessible features</span><h1 id="pageTitle">Feature Home</h1></div></header>
<section id="home" class="view"><div class="grid features"><article class="card feature"><span class="num">01</span><h2>Bank Statement Analysis</h2><p>Upload PDF/JPG statements and run cleansing, categorization, balance, deposit, debit, liability, cash-flow and fraud analysis.</p><button onclick="openFeature('statements','Bank Statement Analysis')">Open Bank Statement Analysis</button></article><article class="card feature"><span class="num">02</span><h2>Income & Employment Verification</h2><p>Use consented Account Aggregator transactions and cross-check income against ITR/GST evidence, filing delays and tax demand.</p><button onclick="openFeature('verification','Income & Employment Verification')">Open Income Verification</button></article><article class="card feature"><span class="num">03</span><h2>Dormant Account & Escheatment</h2><p>Detect, re-engage, track clocks, prepare transfers, enforce maker-checker, manage reclaim, pause automation and export evidence.</p><button onclick="openFeature('dormancy','Dormancy & Escheatment')">Open Dormancy Lifecycle</button></article></div><div class="grid"><article class="card notice"><b>Human authority retained</b><p>Risk insights do not approve lending. Regulated account actions and fund movement remain approval-gated.</p></article><article class="card"><h2>Connected access</h2><p>Every feature uses the same login, secured APIs, audit controls and responsive navigation.</p></article></div></section>
<section id="statements" class="view hidden"><div class="grid"><article class="card"><h2>Upload bank statements</h2><form id="statementUploadForm"><input type="hidden" name="document_type" value="BANK_STATEMENT"><label>PDF password, if protected<input name="password" type="password"></label><label>Bank statement files<input name="files" type="file" accept=".pdf,.jpg,.jpeg" multiple required></label><button>Upload statements</button></form></article><article class="card"><h2>Analyze transactions</h2><p>Submit statement header, extracted transactions and document-upload consent evidence.</p><textarea id="statementPayload" placeholder='{"customer_id":"CUST-1","header":{...},"transactions":[...],"evidence":{"consent_id":"...","consented_at":"...","source":"DOCUMENT_UPLOAD"}}'></textarea><button onclick="analyzeStatement()">Run Bank Statement Analysis</button></article><article class="card" style="grid-column:1/-1"><h2>Analysis result</h2><pre id="statementResult" class="result">No request yet.</pre></article></div></section>
<section id="verification" class="view hidden"><div class="grid"><article class="card"><h2>Upload ITR / GST evidence</h2><form id="verificationUploadForm"><label>Evidence type<select name="document_type"><option>ITR</option><option>GST</option><option>BANK_STATEMENT</option></select></label><label>PDF password, if protected<input name="password" type="password"></label><label>Evidence files<input name="files" type="file" accept=".pdf,.jpg,.jpeg" multiple required></label><button>Upload evidence</button></form></article><article class="card"><h2>Account Aggregator verification</h2><p>Submit purpose-specific consent, AA transactions and reported ITR/GST values.</p><textarea id="verificationPayload" placeholder='{"customer_id":"CUST-1","header":{...},"transactions":[...],"evidence":{"consent_id":"...","consented_at":"...","source":"ACCOUNT_AGGREGATOR","itr_reported_income":0,"gst_reported_turnover":0}}'></textarea><button onclick="verifyIncome()">Run Income Verification</button></article><article class="card" style="grid-column:1/-1"><h2>Verification result</h2><pre id="verificationResult" class="result">No request yet.</pre></article></div></section>
<section id="dormancy" class="view hidden"><div class="grid"><article class="card"><h2>Run lifecycle</h2><textarea id="dormancyPayload">{"account_id":"ACC-100","customer_id":"CUST-1","jurisdiction":"IN-RBI-DEA","balance":1000,"last_customer_activity":"2016-01-01","as_of_date":"2026-01-01"}</textarea><button onclick="jsonCall('/dormancy/cycles','dormancyPayload','dormancyResult')">Run lifecycle</button></article><article class="card"><h2>Deadline alerts</h2><label>As of date<input id="alertDate" type="date"></label><label>Window days<input id="alertDays" type="number" value="90"></label><button onclick="loadAlerts()">Load alerts</button></article><article class="card" style="grid-column:1/-1"><h2>Lifecycle result</h2><pre id="dormancyResult" class="result">No request yet.</pre></article></div></section>
<section id="approvals" class="view hidden"><div class="grid"><article class="card"><h2>Approval queue</h2><button onclick="loadApprovals()">Refresh queue</button><pre id="approvalResult" class="result">No request yet.</pre></article><article class="card"><h2>Maker-checker decision</h2><label>Approval ID<input id="approvalId"></label><label>Decision<select id="decision"><option>APPROVED</option><option>REJECTED</option></select></label><label>Note<input id="decisionNote"></label><button onclick="submitDecision()">Submit decision</button></article></div></section>
</main></section><script>const API='http://127.0.0.1:8001/api/v1';let token='';async function api(path,options={}){options.headers=Object.assign({'Authorization':'Bearer '+token},options.headers||{});const response=await fetch(API+path,options),body=await response.json();if(!response.ok)throw new Error(body.detail||body.title||'Request failed');return body.data}async function loginUser(){try{const body=await fetch(API+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value,user_type:role.value})}).then(async r=>{const x=await r.json();if(!r.ok)throw new Error(x.detail);return x.data});token=body.accessToken;identity.textContent=body.user.display_name+' · '+body.user.role;login.classList.add('hidden');app.classList.remove('hidden')}catch(error){loginError.textContent=error.message}}function showView(id,button,title){document.querySelectorAll('.view').forEach(view=>view.classList.add('hidden'));document.getElementById(id).classList.remove('hidden');document.querySelectorAll('.nav button').forEach(item=>item.classList.remove('active'));if(button)button.classList.add('active');pageTitle.textContent=title}function openFeature(id,title){const button=[...document.querySelectorAll('.nav button')].find(item=>item.textContent.includes(id==='statements'?'Bank Statements':id==='verification'?'Income Verification':'Dormancy'));showView(id,button,title)}async function upload(form,result){try{result.textContent=JSON.stringify(await api('/financial-documents',{method:'POST',body:new FormData(form)}),null,2)}catch(error){result.textContent='Error: '+error.message}}statementUploadForm.onsubmit=e=>{e.preventDefault();upload(statementUploadForm,statementResult)};verificationUploadForm.onsubmit=e=>{e.preventDefault();upload(verificationUploadForm,verificationResult)};async function jsonCall(path,payload,result){try{document.getElementById(result).textContent=JSON.stringify(await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:document.getElementById(payload).value}),null,2)}catch(error){document.getElementById(result).textContent='Error: '+error.message}}function analyzeStatement(){jsonCall('/bank-statement-analyses','statementPayload','statementResult')}function verifyIncome(){jsonCall('/bank-statement-analyses','verificationPayload','verificationResult')}async function loadAlerts(){try{dormancyResult.textContent=JSON.stringify(await api('/dormancy/deadline-alerts?as_of_date='+alertDate.value+'&within_days='+alertDays.value),null,2)}catch(error){dormancyResult.textContent='Error: '+error.message}}async function loadApprovals(){try{approvalResult.textContent=JSON.stringify(await api('/approvals'),null,2)}catch(error){approvalResult.textContent='Error: '+error.message}}async function submitDecision(){try{approvalResult.textContent=JSON.stringify(await api('/approvals/'+approvalId.value+'/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:decision.value,note:decisionNote.value})}),null,2)}catch(error){approvalResult.textContent='Error: '+error.message}}</script></body></html>'''


PAGE = re.sub(r"<aside>.*?</aside>", "", PAGE, flags=re.DOTALL)
PAGE = re.sub(r"async function loginUser\(\)\{.*?\}function showView", "function showView", PAGE)
PAGE = PAGE.replace("let token='';", "").replace("options.headers=Object.assign({'Authorization':'Bearer '+token},options.headers||{});", "options.headers=Object.assign({},options.headers||{});")
PAGE = PAGE.replace("</style>", ".shell{max-width:1180px;margin:0 auto;padding:28px 28px 56px}main{max-width:1180px;margin:0 auto;padding:0}header{align-items:flex-end;padding:18px 0 24px;border-bottom:1px solid #d9e0e7}header h1{font-size:clamp(2rem,4vw,3.4rem);letter-spacing:-.04em}.eyebrow{color:var(--purple)}.features{margin-top:32px;align-items:stretch}.feature{min-height:300px;border-top:0;border-left:5px solid var(--blue);transition:transform .2s ease,box-shadow .2s ease}.feature:hover{transform:translateY(-4px);box-shadow:0 16px 34px #173d6220}.feature:nth-child(2){border-left-color:var(--purple)}.feature:nth-child(3){border-left-color:var(--green)}.feature button{background:var(--navy);border-color:var(--navy);color:#fff}.feature button:hover{background:var(--blue);border-color:var(--blue)}.notice{background:#e8e5ff;color:#4034a5}.notice b{color:var(--navy)}@media(max-width:760px){.shell{padding:18px 16px 40px}.features{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.card{padding:20px}}", 1)


class Handler(BaseHTTPRequestHandler):
    def do_GET(self) -> None:  # noqa: N802
        if self.path not in {"/", "/index.html"}:
            self.send_error(404); return
        data = PAGE.encode("utf-8")
        self.send_response(200); self.send_header("Content-Type", "text/html; charset=utf-8"); self.send_header("Content-Length", str(len(data))); self.end_headers(); self.wfile.write(data)

    def log_message(self, format: str, *args: object) -> None:
        return


def run(host: str = "127.0.0.1", port: int = 8000) -> None:
    print(f"Banking feature home running at http://{host}:{port}")
    ThreadingHTTPServer((host, port), Handler).serve_forever()


if __name__ == "__main__":
    run()
